		t.Errorf("GetFileInfo() Size = %v, want 1024", info.Size())
	}
}

// Test SetFileAttributes
func TestClient_SetFileAttributes_Success(t *testing.T) {
	mockClient := &MockGoSFTPClient{
		SetFileAttrFunc: func(ctx context.Context, remotePath, owner, group, mode string) error {
			if remotePath != "/tmp/test.txt" {
				t.Errorf("SetFileAttributes got remotePath = %v", remotePath)
			}
			if owner != "root" {
				t.Errorf("SetFileAttributes got owner = %v, want 'root'", owner)
			}
			if group != "root" {
				t.Errorf("SetFileAttributes got group = %v, want 'root'", group)
			}
			if mode != "0644" {
				t.Errorf("SetFileAttributes got mode = %v, want '0644'", mode)
			}
			return nil
		},
	}

	client := &Client{
		gosftpClient: mockClient,
		config:       Config{Host: "example.com"},
	}

	err := client.SetFileAttributes(context.Background(), "/tmp/test.txt", "root", "root", "0644")
	if err != nil {
		t.Errorf("SetFileAttributes() error = %v, want nil", err)
	}
}

func TestClient_SetFileAttributes_Error(t *testing.T) {
	expectedErr := errors.New("chmod failed")
	mockClient := &MockGoSFTPClient{
		SetFileAttrFunc: func(ctx context.Context, remotePath, owner, group, mode string) error {
			return expectedErr
		},
	}

	client := &Client{
		gosftpClient: mockClient,
		config:       Config{Host: "example.com"},
	}

	err := client.SetFileAttributes(context.Background(), "/tmp/test.txt", "root", "root", "0644")
	if err != expectedErr {
		t.Errorf("SetFileAttributes() error = %v, want %v", err, expectedErr)
	}
}

// Test Context Cancellation
func TestClient_UploadContent_ContextCancelled(t *testing.T) {
	mockClient := &MockGoSFTPClient{
		UploadContentFunc: func(ctx context.Context, content []byte, remotePath string) error {
			select {
			case <-ctx.Done():
				return ctx.Err()
			default:
				return nil
			}
		},
	}

	client := &Client{
		gosftpClient: mockClient,
		config:       Config{Host: "example.com"},
	}

	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	err := client.UploadContent(ctx, []byte("test"), "/tmp/test.txt")
	if err != context.Canceled {
		t.Errorf("UploadContent() error = %v, want context.Canceled", err)
	}
}

// Test RunCommand with Docker compose output
func TestClient_RunCommand_DockerComposeUp(t *testing.T) {
	composOutput := "Creating network...\nCreating container...\n"
	mockClient := &MockGoSFTPClient{
		RunCommandFunc: func(ctx context.Context, cmd string) (string, string, error) {
			if cmd != "cd /opt/stacks && docker compose -f docker-compose.yaml up -d" {
				t.Errorf("unexpected command: %v", cmd)
			}
			return composOutput, "", nil
		},
	}

	client := &Client{
		gosftpClient: mockClient,
		config:       Config{Host: "example.com"},
	}

	stdout, stderr, err := client.RunCommand(context.Background(), "cd /opt/stacks && docker compose -f docker-compose.yaml up -d")
	if err != nil {
		t.Errorf("RunCommand() error = %v, want nil", err)
	}
	if stdout != composOutput {
		t.Errorf("RunCommand() stdout mismatch")
	}
	if stderr != "" {
		t.Errorf("RunCommand() stderr = %v, want empty", stderr)
	}
}

