	if err != nil {
		t.Errorf("RunCommand() error = %v, want nil", err)
	}
	if stdout != composOutput {
		t.Errorf("RunCommand() stdout mismatch")
	}
	if stderr != "" {
		t.Errorf("RunCommand() stderr = %v, want empty", stderr)
	}
}

