	CloseFunc          func() error
}

func (m *MockGoSFTPClient) UploadFile(ctx context.Context, localPath, remotePath string) error {
	if m.UploadFileFunc != nil {
		return m.UploadFileFunc(ctx, localPath, remotePath)
	}
	return nil
}

