   121→		BastionKeyPath:        config.BastionKeyPath,
   122→		BastionPassword:       config.BastionPassword,
   123→	}
   124→
   125→	gosftpClient, err := gosftp.NewClient(gosftpConfig)
   126→	if err != nil {
   127→		return nil, fmt.Errorf("failed to create gosftp client: %w", err)
   128→	}
   129→
   130→	// For RunCommand support, we need the underlying SSH client
   131→	// We'll keep a separate SSH client for command execution
   132→	var sshClient *ssh.Client
   133→
   134→	return &Client{
   135→		gosftpClient: gosftpClient,
   136→		sshClient:    sshClient,
   137→		config:       config,
   138→	}, nil
   139→}
   140→
   141→func connectToBastion(config Config, timeout time.Duration) (*ssh.Client, error) {
   142→	var authMethods []ssh.AuthMethod
   143→
   144→	if config.BastionPassword != "" {
   145→		authMethods = append(authMethods, ssh.Password(config.BastionPassword))
   146→	} else {
   147→		var keyData []byte
   148→		var err error
   149→
   150→		if config.BastionKey != "" {
   151→			keyData = []byte(config.BastionKey)
   152→		} else if config.BastionKeyPath != "" {
   153→			keyData, err = os.ReadFile(ExpandPath(config.BastionKeyPath))
   154→			if err != nil {
   155→				return nil, fmt.Errorf("failed to read bastion key file: %w", err)
   156→			}
   157→		} else {
   158→			if config.PrivateKey != "" {
   159→				keyData = []byte(config.PrivateKey)
   160→			} else if config.KeyPath != "" {
   161→				keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   162→				if err != nil {
   163→					return nil, fmt.Errorf("failed to read key file for bastion: %w", err)
   164→				}
   165→			} else {
   166→				return nil, fmt.Errorf("no SSH key configured for bastion host")
   167→			}
   168→		}
   169→
   170→		signer, err := ssh.ParsePrivateKey(keyData)
   171→		if err != nil {
   172→			return nil, fmt.Errorf("failed to parse bastion SSH key: %w", err)
   173→		}
   174→		authMethods = append(authMethods, ssh.PublicKeys(signer))
   175→	}
   176→
   177→	bastionUser := config.BastionUser
   178→	if bastionUser == "" {
   179→		bastionUser = config.User
   180→	}
   181→
   182→	bastionPort := config.BastionPort
   183→	if bastionPort == 0 {
   184→		bastionPort = 22
   185→	}
   186→
   187→	hostKeyCallback, err := buildHostKeyCallback(config)
   188→	if err != nil {
   189→		return nil, fmt.Errorf("failed to configure host key verification for bastion: %w", err)
   190→	}
   191→
   192→	bastionConfig := &ssh.ClientConfig{
   193→		User:            bastionUser,
   194→		Auth:            authMethods,
   195→		HostKeyCallback: hostKeyCallback,
   196→		Timeout:         timeout,
   197→	}
   198→
   199→	bastionAddr := fmt.Sprintf("%s:%d", config.BastionHost, bastionPort)
   200→	return ssh.Dial("tcp", bastionAddr, bastionConfig)
   201→}
   202→
   203→func buildHostKeyCallback(config Config) (ssh.HostKeyCallback, error) {
   204→	if config.InsecureIgnoreHostKey {
   205→		return ssh.InsecureIgnoreHostKey(), nil
   206→	}
   207→
   208→	if config.KnownHostsFile != "" {
   209→		expandedPath := ExpandPath(config.KnownHostsFile)
   210→		callback, err := knownhosts.New(expandedPath)
   211→		if err != nil {
   212→			return nil, fmt.Errorf("failed to load known_hosts file %s: %w", expandedPath, err)
   213→		}
   214→		return callback, nil
   215→	}
   216→
   217→	homeDir, err := os.UserHomeDir()
   218→	if err == nil {
   219→		defaultKnownHosts := filepath.Join(homeDir, ".ssh", "known_hosts")
   220→		if _, err := os.Stat(defaultKnownHosts); err == nil {
   221→			callback, err := knownhosts.New(defaultKnownHosts)
   222→			if err == nil {
   223→				return callback, nil
   224→			}
   225→		}
   226→	}
   227→
   228→	return nil, fmt.Errorf("no known_hosts file found and insecure_ignore_host_key is not set; either set insecure_ignore_host_key=true for development/testing or configure known_hosts_file")
   229→}
   230→
   231→// ExpandPath expands ~ to home directory.
   232→func ExpandPath(path string) string {
   233→	if strings.HasPrefix(path, "~/") {
   234→		homeDir, err := os.UserHomeDir()
   235→		if err == nil {
   236→			return filepath.Join(homeDir, path[2:])
   237→		}
   238→	}
   239→	return path
   240→}
   241→
   242→var validOwnerGroupPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_-]*$|^[0-9]+$`)
   243→
   244→func validateOwnerGroup(name, fieldName string) error {
   245→	if name == "" {
   246→		return nil
   247→	}
   248→	if len(name) > 32 {
   249→		return fmt.Errorf("%s name too long (max 32 characters): %s", fieldName, name)
   250→	}
   251→	if !validOwnerGroupPattern.MatchString(name) {
   252→		return fmt.Errorf("invalid %s name (must be alphanumeric, underscore, hyphen, or numeric): %s", fieldName, name)
   253→	}
   254→	return nil
   255→}
   256→
   257→// ShellQuote returns a shell-escaped version of the string.
   258→func ShellQuote(s string) string {
   259→	if s == "" {
   260→		return "''"
   261→	}
   262→	escaped := strings.ReplaceAll(s, "'", "'\"'\"'")
   263→	return "'" + escaped + "'"
   264→}
   265→
   266→var validModePattern = regexp.MustCompile(`^[0-7]{3,4}$`)
   267→
   268→// ValidateMode checks if a file mode string is valid.
   269→func ValidateMode(mode string) error {
   270→	if mode == "" {
   271→		return nil
   272→	}
   273→	if !validModePattern.MatchString(mode) {
   274→		return fmt.Errorf("invalid mode %q: must be 3-4 octal digits (e.g., \"644\", \"0755\")", mode)
   275→	}
   276→	return nil
   277→}
   278→
   279→func buildAuthMethods(config Config) ([]ssh.AuthMethod, error) {
   280→	var authMethods []ssh.AuthMethod
   281→
   282→	authMethod := config.AuthMethod
   283→	if authMethod == "" {
   284→		authMethod = inferAuthMethod(config)
   285→	}
   286→
   287→	switch authMethod {
   288→	case AuthMethodPassword:
   289→		if config.Password == "" {
   290→			return nil, fmt.Errorf("password authentication requires password to be set")
   291→		}
   292→		authMethods = append(authMethods, ssh.Password(config.Password))
   293→
   294→	case AuthMethodCertificate:
   295→		certAuth, err := buildCertificateAuth(config)
   296→		if err != nil {
   297→			return nil, fmt.Errorf("certificate authentication failed: %w", err)
   298→		}
   299→		authMethods = append(authMethods, certAuth)
   300→
   301→	case AuthMethodPrivateKey, "":
   302→		keyAuth, err := buildPrivateKeyAuth(config)
   303→		if err != nil {
   304→			return nil, err
   305→		}
   306→		authMethods = append(authMethods, keyAuth)
   307→	}
   308→
   309→	return authMethods, nil
   310→}
   311→
   312→func inferAuthMethod(config Config) AuthMethod {
   313→	if config.Password != "" {
   314→		return AuthMethodPassword
   315→	}
   316→	if config.Certificate != "" || config.CertificatePath != "" {
   317→		return AuthMethodCertificate
   318→	}
   319→	return AuthMethodPrivateKey
   320→}
   321→
   322→func buildPrivateKeyAuth(config Config) (ssh.AuthMethod, error) {
   323→	var keyData []byte
   324→	var err error
   325→
   326→	if config.PrivateKey != "" {
   327→		keyData = []byte(config.PrivateKey)
   328→	} else if config.KeyPath != "" {
   329→		keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   330→		if err != nil {
   331→			return nil, fmt.Errorf("failed to read SSH key file: %w", err)
   332→		}
   333→	} else {
   334→		return nil, fmt.Errorf("no SSH private key provided (set private_key or key_path)")
   335→	}
   336→
   337→	signer, err := ssh.ParsePrivateKey(keyData)
   338→	if err != nil {
   339→		return nil, fmt.Errorf("failed to parse SSH private key: %w", err)
   340→	}
   341→
   342→	return ssh.PublicKeys(signer), nil
   343→}
   344→
   345→func buildCertificateAuth(config Config) (ssh.AuthMethod, error) {
   346→	var keyData []byte
   347→	var err error
   348→
   349→	if config.PrivateKey != "" {
   350→		keyData = []byte(config.PrivateKey)
   351→	} else if config.KeyPath != "" {
   352→		keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   353→		if err != nil {
   354→			return nil, fmt.Errorf("failed to read private key file: %w", err)
   355→		}
   356→	} else {
   357→		return nil, fmt.Errorf("certificate auth requires private key (set private_key or key_path)")
   358→	}
   359→
   360→	signer, err := ssh.ParsePrivateKey(keyData)
   361→	if err != nil {
   362→		return nil, fmt.Errorf("failed to parse private key: %w", err)
   363→	}
   364→
   365→	var certData []byte
   366→	if config.Certificate != "" {
   367→		certData = []byte(config.Certificate)
   368→	} else if config.CertificatePath != "" {
   369→		certData, err = os.ReadFile(ExpandPath(config.CertificatePath))
   370→		if err != nil {
   371→			return nil, fmt.Errorf("failed to read certificate file: %w", err)
   372→		}
   373→	} else {
   374→		return nil, fmt.Errorf("certificate auth requires certificate (set certificate or certificate_path)")
   375→	}
   376→
   377→	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(certData)
   378→	if err != nil {
   379→		return nil, fmt.Errorf("failed to parse certificate: %w", err)
   380→	}
   381→
   382→	cert, ok := pubKey.(*ssh.Certificate)
   383→	if !ok {
   384→		return nil, fmt.Errorf("provided file is not an SSH certificate")
   385→	}
   386→
   387→	certSigner, err := ssh.NewCertSigner(cert, signer)
   388→	if err != nil {
   389→		return nil, fmt.Errorf("failed to create certificate signer: %w", err)
   390→	}
   391→
   392→	return ssh.PublicKeys(certSigner), nil
   393→}
   394→
   395→// Close closes the gosftp client and SSH connections.
   396→func (c *Client) Close() error {
   397→	if c.gosftpClient != nil {
   398→		return c.gosftpClient.Close()
   399→	}
   400→	return nil
   401→}
   402→
   403→// UploadFile uploads a local file to the remote host.
   404→func (c *Client) UploadFile(ctx context.Context, localPath, remotePath string) error {
   405→	return c.gosftpClient.UploadFile(ctx, localPath, remotePath)
   406→}
   407→
   408→// UploadContent uploads content directly to the remote host.
   409→// Since gosftp doesn't have a direct UploadContent method, we write to a temp file first.
   410→func (c *Client) UploadContent(ctx context.Context, content []byte, remotePath string) error {
   411→	// Write content to a temporary file
   412→	tmpFile, err := os.CreateTemp("", "upload-*")
   413→	if err != nil {
   414→		return fmt.Errorf("failed to create temporary file: %w", err)
   415→	}
   416→	defer os.Remove(tmpFile.Name())
   417→
   418→	if _, err := tmpFile.Write(content); err != nil {
   419→		tmpFile.Close()
   420→		return fmt.Errorf("failed to write to temporary file: %w", err)
   421→	}
   422→	tmpFile.Close()
   423→
   424→	// Upload the temporary file
   425→	return c.gosftpClient.UploadFile(ctx, tmpFile.Name(), remotePath)
   426→}
   427→
   428→// GetFileHash returns the SHA256 hash of a remote file.
   429→func (c *Client) GetFileHash(ctx context.Context, remotePath string) (string, error) {
   430→	return c.gosftpClient.GetFileHash(ctx, remotePath)
   431→}
   432→
   433→// SetFileAttributes sets ownership and permissions on a remote file.
   434→func (c *Client) SetFileAttributes(ctx context.Context, remotePath, owner, group, mode string) error {
   435→	if err := validateOwnerGroup(owner, "owner"); err != nil {
   436→		return err
   437→	}
   438→	if err := validateOwnerGroup(group, "group"); err != nil {
   439→		return err
   440→	}
   441→	if err := ValidateMode(mode); err != nil {
   442→		return err
   443→	}
   444→
   445→	return c.gosftpClient.SetFileAttributes(ctx, remotePath, owner, group, mode)
   446→}
   447→
   448→// DeleteFile removes a file from the remote host.
   449→func (c *Client) DeleteFile(ctx context.Context, remotePath string) error {
   450→	return c.gosftpClient.DeleteFile(ctx, remotePath)
   451→}
   452→
   453→// FileExists checks if a file exists on the remote host.
   454→func (c *Client) FileExists(ctx context.Context, remotePath string) (bool, error) {
   455→	return c.gosftpClient.FileExists(ctx, remotePath)
   456→}
   457→
   458→// GetFileInfo returns information about a remote file.
   459→func (c *Client) GetFileInfo(ctx context.Context, remotePath string) (os.FileInfo, error) {
   460→	return c.gosftpClient.GetFileInfo(ctx, remotePath)
   461→}
   462→
   463→// ReadFileContent reads the content of a remote file.
   464→func (c *Client) ReadFileContent(ctx context.Context, remotePath string, maxBytes int64) ([]byte, error) {
   465→	return c.gosftpClient.ReadFileContent(ctx, remotePath, maxBytes)
   466→}
   467→
   468→// RunCommand executes a command on the remote host.
   469→// Returns stdout, stderr, and any error.
   470→func (c *Client) RunCommand(ctx context.Context, command string) (string, string, error) {
   471→	// Check if context is already cancelled
   472→	if err := ctx.Err(); err != nil {
   473→		return "", "", fmt.Errorf("context already cancelled: %w", err)
   474→	}
   475→
   476→	// For now, we need to create an SSH client for command execution
   477→	// since gosftp focuses on SFTP operations
   478→	authMethods, err := buildAuthMethods(c.config)
   479→	if err != nil {
   480→		return "", "", fmt.Errorf("failed to build auth methods: %w", err)
   481→	}
   482→
   483→	hostKeyCallback, err := buildHostKeyCallback(c.config)
   484→	if err != nil {
   485→		return "", "", fmt.Errorf("failed to build host key callback: %w", err)
   486→	}
   487→
   488→	timeout := c.config.Timeout
   489→	if timeout == 0 {
   490→		timeout = 30 * time.Second
   491→	}
   492→
   493→	// If context has a deadline, use the smaller of context deadline and configured timeout
   494→	if deadline, ok := ctx.Deadline(); ok {
   495→		timeUntilDeadline := time.Until(deadline)
   496→		if timeUntilDeadline > 0 && timeUntilDeadline < timeout {
   497→			timeout = timeUntilDeadline
   498→		}
   499→	}
   500→
   501→	port := c.config.Port
   502→	if port == 0 {
   503→		port = 22
   504→	}
   505→
   506→	sshConfig := &ssh.ClientConfig{
   507→		User:            c.config.User,
   508→		Auth:            authMethods,
   509→		HostKeyCallback: hostKeyCallback,
   510→		Timeout:         timeout,
   511→	}
   512→
   513→	targetAddr := fmt.Sprintf("%s:%d", c.config.Host, port)
   514→
   515→	// Check context before establishing connections
   516→	if err := ctx.Err(); err != nil {
   517→		return "", "", fmt.Errorf("context cancelled before connecting: %w", err)
   518→	}
   519→
   520→	var sshClient *ssh.Client
   521→	var bastionClient *ssh.Client
   522→
   523→	if c.config.BastionHost != "" {
   524→		bastionClient, err = connectToBastion(c.config, timeout)
   525→		if err != nil {
   526→			return "", "", fmt.Errorf("failed to connect to bastion host: %w", err)
   527→		}
   528→		defer func() {
   529→			if closeErr := bastionClient.Close(); closeErr != nil {
   530→				// Log but don't fail - bastion close error shouldn't block command execution
   531→				_ = closeErr
   532→			}
   533→		}()
   534→
   535→		conn, err := bastionClient.Dial("tcp", targetAddr)
   536→		if err != nil {
   537→			return "", "", fmt.Errorf("failed to dial target through bastion: %w", err)
   538→		}
   539→
   540→		ncc, chans, reqs, err := ssh.NewClientConn(conn, targetAddr, sshConfig)
   541→		if err != nil {
   542→			if closeErr := conn.Close(); closeErr != nil {
   543→				_ = closeErr
   544→			}
   545→			return "", "", fmt.Errorf("failed to create SSH connection through bastion: %w", err)
   546→		}
   547→
   548→		sshClient = ssh.NewClient(ncc, chans, reqs)
   549→	} else {
   550→		sshClient, err = ssh.Dial("tcp", targetAddr, sshConfig)
   551→		if err != nil {
   552→			return "", "", fmt.Errorf("failed to connect to %s: %w", targetAddr, err)
   553→		}
   554→	}
   555→	defer func() {
   556→		if closeErr := sshClient.Close(); closeErr != nil {
   557→			// Log but don't fail - close error shouldn't block command result
   558→			_ = closeErr
   559→		}
   560→	}()
   561→
   562→	session, err := sshClient.NewSession()
   563→	if err != nil {
   564→		return "", "", fmt.Errorf("failed to create SSH session: %w", err)
   565→	}
   566→	defer func() {
   567→		if closeErr := session.Close(); closeErr != nil {
   568→			// Log but don't fail - close error shouldn't block command result
   569→			_ = closeErr
   570→		}
   571→	}()
   572→
   573→	var stdout, stderr bytes.Buffer
   574→	session.Stdout = &stdout
   575→	session.Stderr = &stderr
   576→
   577→	err = session.Run(command)
   578→	return stdout.String(), stderr.String(), err
   579→}
