   581→// IsBinaryContent checks if content appears to be binary.
   582→func IsBinaryContent(content []byte) bool {
   583→	for _, b := range content {
   584→		if b == 0 {
   585→			return true
   586→		}
   587→	}
   588→	return false
   589→}
