		certData = []byte(config.Certificate)
	} else if config.CertificatePath != "" {
		certData, err = deps.FileReader(ExpandPath(config.CertificatePath))
		if err != nil {
			return nil, fmt.Errorf("failed to read certificate file: %w", err)
		}
	} else {
